INSERT INTO private.baseline_bank(qualification,academic_level,position,topic,skill,difficulty,prompt,choices,correct_text,explanation) VALUES
('GCSE','foundation',1,'Number','Adding integers',1,'Calculate 18 + 27.',jsonb_build_array('35','45','46','55'),'45','18 + 27 = 45.'),
('GCSE','foundation',2,'Number','Decimal addition',1,'Calculate 3.6 + 2.75.',jsonb_build_array('6.35','5.35','6.25','6.75'),'6.35','Write 3.60 + 2.75 = 6.35, aligning place values.'),
('GCSE','foundation',3,'Fractions','Fraction of an amount',1,'Find 3/4 of 48.',jsonb_build_array('12','24','36','40'),'36','48 ÷ 4 = 12 and 3 × 12 = 36.'),
('GCSE','foundation',4,'Fractions','Adding fractions',2,'Calculate 2/5 + 1/10.',jsonb_build_array('3/15','3/10','1/2','2/15'),'1/2','2/5 = 4/10, so 4/10 + 1/10 = 5/10 = 1/2.'),
('GCSE','foundation',5,'Percentages','Percentage of a quantity',2,'Calculate 15% of 240.',jsonb_build_array('24','36','42','45'),'36','10% of 240 is 24 and 5% is 12. Total 36.'),
('GCSE','foundation',6,'Ratio','Dividing in a ratio',2,'£55 is shared in the ratio 4 : 7. What is the smaller share?',jsonb_build_array('£20','£25','£28','£35'),'£20','There are 11 parts; one part is £5, so the smaller share is 4 × £5 = £20.'),
('GCSE','foundation',7,'Factors and multiples','Lowest common multiple',2,'Find the lowest common multiple of 12 and 18.',jsonb_build_array('6','18','36','72'),'36','Multiples of 12 include 12,24,36; multiples of 18 include 18,36. LCM = 36.'),
('GCSE','foundation',8,'Fractions','Simplest form',2,'Simplify 84/126 fully.',jsonb_build_array('4/6','2/3','3/4','1/2'),'2/3','The highest common factor is 42, so 84/126 = 2/3.'),
('GCSE','foundation',9,'Algebra','Solving linear equations',2,'Solve 3x + 7 = 28.',jsonb_build_array('5','6','7','9'),'7','Subtract 7 and divide by 3: x = 21/3 = 7.'),
('GCSE','foundation',10,'Algebra','Expanding one bracket',2,'Expand 2(3x − 4).',jsonb_build_array('6x − 4','5x − 8','6x − 8','6x + 8'),'6x − 8','Multiply both terms inside the bracket by 2.'),
('GCSE','foundation',11,'Geometry','Area of a trapezium',3,'A trapezium has parallel sides of 7 cm and 13 cm and a perpendicular height of 6 cm. Find its area.',jsonb_build_array('36 cm²','60 cm²','78 cm²','120 cm²'),'60 cm²','Area = (7 + 13) × 6 ÷ 2 = 60 cm².'),
('GCSE','foundation',12,'Geometry','Circle circumference',3,'A circle has radius 7 cm. Taking π = 22/7, what is its circumference?',jsonb_build_array('22 cm','44 cm','49 cm','154 cm'),'44 cm','Circumference = 2πr = 2 × (22/7) × 7 = 44 cm.'),
('GCSE','foundation',13,'Geometry','Pythagoras',3,'A right-angled triangle has shorter sides 6 cm and 8 cm. Find the hypotenuse.',jsonb_build_array('7 cm','10 cm','12 cm','14 cm'),'10 cm','Hypotenuse² = 6² + 8² = 100, so it is 10 cm.'),
('GCSE','foundation',14,'Geometry','Angles in triangles',2,'Two angles of a triangle are 48° and 67°. Find the third angle.',jsonb_build_array('55°','60°','65°','75°'),'65°','Triangle angles add to 180°: 180 − 48 − 67 = 65°.'),
('GCSE','foundation',15,'Statistics','Calculating a mean',2,'Find the mean of 4, 7, 9 and 12.',jsonb_build_array('7','8','9','10'),'8','The total is 32. Divide by 4 to get 8.'),
('GCSE','foundation',16,'Statistics','Median',2,'Find the median of 3, 6, 8, 12 and 15.',jsonb_build_array('6','7','8','9'),'8','The five values are in order; the middle value is 8.'),
('GCSE','foundation',17,'Probability','Simple probability',2,'A bag contains 5 red, 3 blue and 2 green counters. What is the probability of choosing a blue counter?',jsonb_build_array('1/5','3/10','1/3','3/5'),'3/10','There are 10 counters and 3 blue: probability = 3/10.'),
('GCSE','foundation',18,'Sequences','Arithmetic sequences',2,'Find the next term in the sequence 5, 9, 13, 17, ...',jsonb_build_array('18','20','21','22'),'21','Add 4 each time: 17 + 4 = 21.'),
('GCSE','foundation',19,'Number','Standard form',3,'Write 0.00056 in standard form.',jsonb_build_array('5.6 × 10⁻⁴','5.6 × 10⁻³','56 × 10⁻⁵','0.56 × 10⁻³'),'5.6 × 10⁻⁴','The first number must be at least 1 and less than 10: 0.00056 = 5.6 × 10⁻⁴.'),
('GCSE','foundation',20,'Rates','Speed, distance and time',2,'A train travels 150 km in 3 hours at a constant speed. Find its speed.',jsonb_build_array('30 km/h','45 km/h','50 km/h','450 km/h'),'50 km/h','Speed = distance ÷ time = 150 ÷ 3 = 50 km/h.')
