INSERT INTO private.baseline_bank(qualification,academic_level,position,topic,skill,difficulty,prompt,choices,correct_text,explanation) VALUES
('GCSE','higher',1,'Surds','Simplifying surds',3,'Simplify √72.',jsonb_build_array('3√8','6√2','12√2','2√6'),'6√2','√72 = √(36 × 2) = 6√2.'),
('GCSE','higher',2,'Surds','Rationalising a denominator',3,'Simplify 5/√5.',jsonb_build_array('5√5','1/√5','√5','25'),'√5','Multiply numerator and denominator by √5: 5√5/5 = √5.'),
('GCSE','higher',3,'Quadratics','Factorising quadratics',3,'Solve x² − 7x + 12 = 0.',jsonb_build_array('x = −3 or −4','x = 2 or 6','x = 3 or 4','x = −2 or −6'),'x = 3 or 4','(x − 3)(x − 4) = 0, giving x = 3 or 4.'),
('GCSE','higher',4,'Quadratics','Quadratic formula and factorisation',4,'Solve 2x² − 5x − 3 = 0.',jsonb_build_array('x = 3 or −1/2','x = −3 or 1/2','x = 3 or 1/2','x = −3 or −1/2'),'x = 3 or −1/2','2x² − 5x − 3 = (2x + 1)(x − 3).'),
('GCSE','higher',5,'Indices','Negative indices',3,'Simplify (x⁵ × x⁻²) / x, for x ≠ 0.',jsonb_build_array('x⁸','x³','x²','x⁻²'),'x²','Add indices when multiplying and subtract when dividing: 5 − 2 − 1 = 2.'),
('GCSE','higher',6,'Algebra','Simultaneous equations',3,'Solve 2x + y = 11 and x − y = 1.',jsonb_build_array('x = 3, y = 5','x = 4, y = 3','x = 5, y = 1','x = 2, y = 7'),'x = 4, y = 3','Adding the equations gives 3x = 12, so x = 4 and y = 3.'),
('GCSE','higher',7,'Coordinate geometry','Gradient',3,'Find the gradient of the line through (1, 3) and (5, 11).',jsonb_build_array('1/2','2','4','8'),'2','Gradient = (11 − 3)/(5 − 1) = 8/4 = 2.'),
('GCSE','higher',8,'Quadratics','Completing the square',4,'Find the minimum value of y = x² − 6x + 11.',jsonb_build_array('−2','2','3','11'),'2','x² − 6x + 11 = (x − 3)² + 2, so minimum y is 2.'),
('GCSE','higher',9,'Trigonometry','Right-triangle trigonometry',3,'For an acute angle θ, sin θ = 3/5. Which is closest to θ?',jsonb_build_array('30.0°','36.9°','53.1°','60.0°'),'36.9°','θ = sin⁻¹(0.6) ≈ 36.87°.'),
('GCSE','higher',10,'Geometry','Sectors',4,'A sector of radius 8 cm has angle 90°. Find its area.',jsonb_build_array('8π cm²','12π cm²','16π cm²','32π cm²'),'16π cm²','Area = 90/360 × π × 8² = 16π cm².'),
('GCSE','higher',11,'Probability','Independent events',3,'Two independent events have probabilities 0.3 and 0.4. Find P(both occur).',jsonb_build_array('0.07','0.12','0.35','0.70'),'0.12','Multiply independent probabilities: 0.3 × 0.4 = 0.12.'),
('GCSE','higher',12,'Probability','Without replacement',4,'A bag contains 4 red and 6 blue counters. Two are chosen without replacement. Find P(both red).',jsonb_build_array('4/25','2/15','4/15','1/5'),'2/15','Probability = 4/10 × 3/9 = 12/90 = 2/15.'),
('GCSE','higher',13,'Algebra','Modulus equations',4,'Solve |2x − 3| = 5.',jsonb_build_array('x = 4 only','x = 4 or −1','x = 1 or −4','x = −1 only'),'x = 4 or −1','2x − 3 = ±5, so x = 4 or x = −1.'),
('GCSE','higher',14,'Inequalities','Quadratic inequalities',4,'Solve x² − 9 < 0.',jsonb_build_array('x < −3 or x > 3','−3 < x < 3','x > −3','x < 3'),'−3 < x < 3','(x − 3)(x + 3) is negative between its roots.'),
('GCSE','higher',15,'Functions','Composite functions',4,'If f(x) = 2x + 1 and g(x) = x², find f(g(3)).',jsonb_build_array('10','13','19','37'),'19','g(3) = 9, so f(g(3)) = f(9) = 19.'),
('GCSE','higher',16,'Percentages','Compound percentage changes',3,'A price of £200 increases by 10% then decreases by 10%. What is the final price?',jsonb_build_array('£180','£198','£200','£202'),'£198','200 × 1.1 × 0.9 = 198.'),
('GCSE','higher',17,'Bounds','Upper bounds',4,'A length is 5.6 cm correct to 1 decimal place. What is its upper bound?',jsonb_build_array('5.55 cm','5.6 cm','5.65 cm','5.7 cm'),'5.65 cm','Values round to 5.6 when 5.55 ≤ length < 5.65, so upper bound is 5.65 cm.'),
('GCSE','higher',18,'Algebra','Simplifying algebraic fractions',4,'Simplify (x² − 9)/(x − 3), for x ≠ 3.',jsonb_build_array('x − 3','x + 3','x² + 3','1/(x + 3)'),'x + 3','Factor numerator as (x − 3)(x + 3), then cancel x − 3 (provided x ≠ 3).'),
('GCSE','higher',19,'Number','Standard form calculations',3,'Calculate (4 × 10⁵)/(2 × 10⁻³).',jsonb_build_array('2 × 10²','2 × 10⁸','8 × 10⁸','2 × 10⁻⁸'),'2 × 10⁸','Divide coefficients and subtract powers: 4/2 × 10^(5−(−3)) = 2 × 10⁸.'),
('GCSE','higher',20,'Geometry','Volume of a cone',4,'Find the exact volume of a cone with radius 3 cm and perpendicular height 4 cm.',jsonb_build_array('9π cm³','12π cm³','24π cm³','36π cm³'),'12π cm³','Volume = (1/3)πr²h = (1/3)π × 9 × 4 = 12π cm³.')
